package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Integer;
    attribute accumulatedMs : Integer := 0;
    attribute printGate : Boolean := false;
    perform action tick {
      first start;
      then assign printGate := false;
      then assign accumulatedMs := accumulatedMs + io_0;
      then if ((accumulatedMs) >= (2000)) {
        first start;
        then assign accumulatedMs := accumulatedMs - 2000;
        then assign printGate := true;
      }
    }
